SELECT
    COUNT(CASE WHEN f.first_ct IS NULL OR f.first_ct >= #{start} THEN 1 END) AS newUserCnt,
    COUNT(CASE WHEN f.first_ct < #{start} THEN 1 END) AS oldUserCnt
FROM t_link_access_log_stats l
LEFT JOIN (
    SELECT ip, MIN(create_time) AS first_ct
    FROM t_link_access_log_stats
    WHERE full_short_url = #{fullShortUrl}
    GROUP BY ip
) f ON f.ip = l.ip
WHERE l.full_short_url = #{fullShortUrl}
  AND l.create_time >= #{start}
  AND l.create_time < DATE_ADD(#{end}, INTERVAL 1 DAY)

SELECT full_short_url, user, ip FROM t_link_access_log_stats WHERE full_short_url IN
#{url}
AND create_time >= #{start} AND create_time < DATE_ADD(#{end}, INTERVAL 1 DAY) GROUP BY full_short_url, user, ip

